using Microsoft.VisualStudio.TestTools.UnitTesting;
using Payments;

namespace Payments.Tests;

[TestClass]
public sealed class ChargeTests
{
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup() => _gateway = new PaymentGateway();

    // --- Happy-path ---

    [TestMethod]
    public async Task ChargeAsync_ValidTokenAndAmount_ReturnsSuccess()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 50.00m);

        Assert.IsTrue(result.Success);
        Assert.IsFalse(string.IsNullOrWhiteSpace(result.ChargeId));
    }

    [TestMethod]
    public async Task ChargeAsync_MinimumAmount_ReturnsSuccess()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 0.01m);

        Assert.IsTrue(result.Success);
    }

    [TestMethod]
    public async Task ChargeAsync_LargeAmount_ReturnsSuccess()
    {
        var result = await _gateway.ChargeAsync("tok_valid", 999_999.99m);

        Assert.IsTrue(result.Success);
    }

    // --- Validation / negative ---

    [TestMethod]
    public async Task ChargeAsync_NullToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.ChargeAsync(null!, 10.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_EmptyToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.ChargeAsync(string.Empty, 10.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_WhitespaceToken_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.ChargeAsync("   ", 10.00m));
    }

    [TestMethod]
    public async Task ChargeAsync_ZeroAmount_ThrowsArgumentOutOfRangeException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentOutOfRangeException>(
            () => _gateway.ChargeAsync("tok_valid", 0m));
    }

    [TestMethod]
    public async Task ChargeAsync_NegativeAmount_ThrowsArgumentOutOfRangeException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentOutOfRangeException>(
            () => _gateway.ChargeAsync("tok_valid", -5.00m));
    }

    // --- Uniqueness ---

    [TestMethod]
    public async Task ChargeAsync_TwoCalls_ReturnDistinctChargeIds()
    {
        var r1 = await _gateway.ChargeAsync("tok_a", 10m);
        var r2 = await _gateway.ChargeAsync("tok_b", 20m);

        Assert.AreNotEqual(r1.ChargeId, r2.ChargeId);
    }
}

[TestClass]
public sealed class RefundTests
{
    private PaymentGateway _gateway = null!;

    [TestInitialize]
    public void Setup() => _gateway = new PaymentGateway();

    // --- Happy-path ---

    [TestMethod]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccess()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 25.00m);
        var refund = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(refund.Success);
        Assert.IsFalse(string.IsNullOrWhiteSpace(refund.RefundId));
    }

    // --- Validation / negative ---

    [TestMethod]
    public async Task RefundAsync_NullChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.RefundAsync(null!));
    }

    [TestMethod]
    public async Task RefundAsync_EmptyChargeId_ThrowsArgumentException()
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _gateway.RefundAsync(string.Empty));
    }

    [TestMethod]
    public async Task RefundAsync_UnknownChargeId_ReturnsFailure()
    {
        var result = await _gateway.RefundAsync("chg_nonexistent");

        Assert.IsFalse(result.Success);
    }

    // --- Duplicate refund ---

    [TestMethod]
    public async Task RefundAsync_SameChargeTwice_SecondRefundFails()
    {
        var charge = await _gateway.ChargeAsync("tok_valid", 30.00m);
        var first  = await _gateway.RefundAsync(charge.ChargeId);
        var second = await _gateway.RefundAsync(charge.ChargeId);

        Assert.IsTrue(first.Success);
        Assert.IsFalse(second.Success);
    }

    // --- Uniqueness ---

    [TestMethod]
    public async Task RefundAsync_TwoRefunds_ReturnDistinctRefundIds()
    {
        var c1 = await _gateway.ChargeAsync("tok_a", 10m);
        var c2 = await _gateway.ChargeAsync("tok_b", 20m);

        var r1 = await _gateway.RefundAsync(c1.ChargeId);
        var r2 = await _gateway.RefundAsync(c2.ChargeId);

        Assert.AreNotEqual(r1.RefundId, r2.RefundId);
    }
}

